// src/components/Navbar.jsx

import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useSelector } from 'react-redux';
import { FaShoppingCart, FaHeart } from 'react-icons/fa';
import { categories } from '../api/categories';

function Navbar() {
  const cartCount = useSelector(state => state.cart.items.reduce((acc, item) => acc + item.quantity, 0));
  const wishlistCount = useSelector(state => state.wishlist.items.length);

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('');
  const navigate = useNavigate();

  const handleSearch = () => {
    const queryParams = new URLSearchParams();
    if (searchTerm.trim()) queryParams.set('q', searchTerm.trim());
    if (selectedCategory) queryParams.set('category', selectedCategory);
    navigate(`/search?${queryParams.toString()}`);
  };

  useEffect(() => {
    if (selectedCategory && !searchTerm) {
      const queryParams = new URLSearchParams();
      queryParams.set('category', selectedCategory);
      navigate(`/search?${queryParams.toString()}`);
    }
  }, [selectedCategory]);

  return (
    <nav className="navbar">
      <Link to="/" className="nav-logo">📚 BookStore</Link>

      <div className="nav-search">
        <select
          value={selectedCategory}
          onChange={e => setSelectedCategory(e.target.value)}
        >
          <option value="">All Categories</option>
          {categories.map(cat => (
            <option key={cat.query} value={cat.query}>{cat.name}</option>
          ))}
        </select>

        <input
          type="text"
          placeholder="Search by title, author..."
          value={searchTerm}
          onChange={e => setSearchTerm(e.target.value)}
        />
        <button onClic={handleSearch}>Search</button>
      </div>

      <div className="nav-links">
        <Link to="/wishlist" className="nav-icon">
          <FaHeart />
          {wishlistCount > 0 && <span className="badge">{wishlistCount}</span>}
        </Link>

        <Link to="/cart" className="nav-icon">
          <FaShoppingCart />
          {cartCount > 0 && <span className="badge">{cartCount}</span>}
        </Link>
      </div>
    </nav>
  );
}

export default Navbar;
